-- Typed extraction destination schema.
-- This migration intentionally renames the old destinations at the end.
-- Application code must be cut over to the typed tables before ingestion resumes.

begin;

create or replace function public._typed_num(v text)
returns numeric language sql immutable as $$
  select case when nullif(trim(v), '') is null then null
    when trim(v) ~ '^-?[0-9]+(\.[0-9]+)?$' then trim(v)::numeric end
$$;

create or replace function public._typed_money(v numeric, unit text)
returns numeric language sql immutable as $$
  select case lower(coalesce(unit, ''))
    when 'cr' then v * 10000000
    when 'crore' then v * 10000000
    when 'lac' then v * 100000
    when 'lakh' then v * 100000
    when 'k' then v * 1000
    when 'thousand' then v * 1000
    else v end
$$;

create or replace function public._typed_asset(asset text, property text, body text)
returns text language sql immutable as $$
  select case
    when lower(coalesce(asset,'') || ' ' || coalesce(property,'') || ' ' || coalesce(body,'')) ~
      '(office|shop|showroom|warehouse|godown|industrial|commercial|retail|bare.?shell|warm.?shell|chargeable area|ceiling height|mezzanine|cabin|workstation|conference room|\bpsf\b|\bcam\b|lease deed|power load|\bkw\b|food court)'
      then 'commercial'
    else 'residential'
  end
$$;

create or replace function public._typed_tx(intent text, tx text, body text)
returns text language sql immutable as $$
  select case
    when lower(coalesce(tx,'') || ' ' || coalesce(intent,'') || ' ' || coalesce(body,'')) ~
      '(rent|rental|lease|monthly|per month|deposit|tenancy|lock.?in|notice period|lease out)' then 'rent'
    else 'sale'
  end
$$;

