-- Requirement envelope and type-specific demand fields.
create table if not exists public.residential_sale_requirements (like public.residential_sale_listings including defaults excluding constraints, constraint residential_sale_requirements_asset check (asset_type='residential'), constraint residential_sale_requirements_tx check (transaction_type='sale'), constraint residential_sale_requirements_pk primary key (id));
alter table public.residential_sale_requirements alter column id add generated by default as identity;
alter table public.residential_sale_requirements drop column if exists total_asking_price, drop column if exists price_per_sqft, drop column if exists price_basis, drop column if exists price_raw_text, drop column if exists price_qualifier;
alter table public.residential_sale_requirements add column if not exists budget_min numeric, add column if not exists budget_max numeric, add column if not exists budget_currency text default 'INR', add column if not exists area_min_sqft numeric, add column if not exists area_max_sqft numeric, add column if not exists locality_options text[] default '{}', add column if not exists is_flexible boolean default false, add column if not exists urgency text, add column if not exists status text default 'active', add column if not exists bhk_options numeric[] default '{}', add column if not exists configuration_preference text[] default '{}', add column if not exists carpet_area_min_sqft numeric, add column if not exists carpet_area_max_sqft numeric, add column if not exists built_up_area_min_sqft numeric, add column if not exists built_up_area_max_sqft numeric, add column if not exists budget_per_sqft_max numeric, add column if not exists furnishing_preference text, add column if not exists possession_preference text, add column if not exists age_preference text, add column if not exists micro_market_options text[] default '{}', add column if not exists building_preferences text[] default '{}', add column if not exists car_parking_min integer, add column if not exists floor_preference text, add column if not exists view_preference text[] default '{}', add column if not exists amenity_requirements text[] default '{}', add column if not exists buyer_type text, add column if not exists nationality text, add column if not exists loan_preapproved boolean, add column if not exists transaction_nature text, add column if not exists brokerage_willingness text;

create table if not exists public.residential_rent_requirements (like public.residential_sale_requirements including defaults excluding constraints, constraint residential_rent_requirements_asset check (asset_type='residential'), constraint residential_rent_requirements_tx check (transaction_type='rent'), constraint residential_rent_requirements_pk primary key (id));
alter table public.residential_rent_requirements alter column id add generated by default as identity;
alter table public.residential_rent_requirements add column if not exists deposit_budget_max numeric, add column if not exists available_from date, add column if not exists tenant_type text, add column if not exists has_pets boolean default false, add column if not exists sharing_acceptable boolean default false, add column if not exists food_preference text, add column if not exists lease_term_preference text;

create table if not exists public.commercial_sale_requirements (like public.residential_sale_requirements including defaults excluding constraints, constraint commercial_sale_requirements_asset check (asset_type='commercial'), constraint commercial_sale_requirements_tx check (transaction_type='sale'), constraint commercial_sale_requirements_pk primary key (id));
alter table public.commercial_sale_requirements alter column id add generated by default as identity;
alter table public.commercial_sale_requirements add column if not exists commercial_use_type text[] default '{}', add column if not exists chargeable_area_max_sqft numeric, add column if not exists fitout_preference text, add column if not exists min_ceiling_height text, add column if not exists needs_mezzanine boolean default false, add column if not exists needs_lift boolean default false, add column if not exists needs_power_backup boolean default false, add column if not exists needs_central_ac boolean default false, add column if not exists min_power_load_kw numeric, add column if not exists oc_required boolean default true;

create table if not exists public.commercial_rent_requirements (like public.commercial_sale_requirements including defaults excluding constraints, constraint commercial_rent_requirements_asset check (asset_type='commercial'), constraint commercial_rent_requirements_tx check (transaction_type='rent'), constraint commercial_rent_requirements_pk primary key (id));
alter table public.commercial_rent_requirements alter column id add generated by default as identity;
alter table public.commercial_rent_requirements add column if not exists deposit_budget_max numeric, add column if not exists budget_per_sqft_max numeric, add column if not exists min_cabin_count integer, add column if not exists min_workstation_count integer, add column if not exists needs_conference_room boolean default false, add column if not exists needs_pantry boolean default false, add column if not exists needs_server_room boolean default false, add column if not exists lease_term_preference text, add column if not exists max_lock_in_months integer, add column if not exists max_notice_period_months integer, add column if not exists company_type text, add column if not exists team_size integer;

-- Add the requirement envelope constraints after LIKE-based creation.
do $$ declare t text; begin foreach t in array array['residential_sale_requirements','residential_rent_requirements','commercial_sale_requirements','commercial_rent_requirements'] loop
  execute format('alter table public.%I add constraint %I check (urgency is null or urgency in (''urgent'',''normal'',''flexible''))', t, t||'_urgency');
  execute format('alter table public.%I add constraint %I check (status is null or status in (''active'',''fulfilled'',''expired'',''withdrawn''))', t, t||'_status');
end loop; exception when duplicate_object then null; end $$;

-- Backfill typed listings from parsed_output. NULL asset_type is classified from the
-- raw message; those rows are deliberately marked for review.
with src as (
  select p.*, r.message as source_message, lower(coalesce(p.asset_type,'') || ' ' || coalesce(p.property_type,'')) as source_type,
    public._typed_asset(p.asset_type,p.property_type,r.message) as a,
    public._typed_tx(p.intent,p.transaction_type,r.message) as tx,
    coalesce(p.carpet_area_sqft, public._typed_num(p.ai_extraction->>'carpet_area_sqft'), p.area_sqft) as carpet,
    coalesce(p.built_up_area_sqft, public._typed_num(p.ai_extraction->>'built_up_area_sqft')) as built,
    coalesce(p.total_asking_price,p.monthly_rent,public._typed_money(p.price,p.price_unit)) as amount,
    case when lower(coalesce(p.price_unit,''))='psf' then p.price end as psf
  from public.parsed_output p left join public.raw_messages r on r.id=p.raw_message_id
  where lower(coalesce(p.message_type,'')) not in ('buy','requirement') and lower(coalesce(p.intent,'')) not in ('buy','requirement','buyer')
), ins as (
  select src.*, md5('parsed_output:'||id::text) fp from src
)
