select raw_message_id,tenant_id,coalesce(listing_index,0),fp,building_name,location_raw,location_raw,micro_market,landmark_name,street_name,case when exists(select 1 from brokers b where b.id=src.broker_id) then src.broker_id end,broker_name,broker_phone,group_name,summary_title,normalized_message,coalesce(raw_payload,'{}'),ai_extraction,coalesce(deal_tags,'{}'),coalesce(additional_charges,'[]'),coalesce(validation_flags,'[]'),needs_review or asset_type is null or (tx='sale' and amount is null),case when confidence>=.8 then 'high' when confidence>=.5 then 'medium' else 'low' end,coalesce(corrected_fields,'{}'),correction_confidence,corrected_at,created_at,now(),id,public._typed_num(regexp_replace(coalesce(bhk,''),'[^0-9.]','','g')),configuration_type,bathroom_count,carpet,built,area,case when a='residential' and tx='sale' then amount end,psf,price_basis,ai_extraction->'price'->>'raw_price_text',furnishing_canonical,possession_status,case when possession_date ~ '^\d{4}-\d{2}-\d{2}$' then possession_date::date end,car_parking_count,parking_type,floor_range,amenities_unverified_claim,oc_status,brokerage_type,developer
from ins src where a='residential' and tx='sale';

