select raw_message_id,tenant_id,coalesce(listing_index,0),fp,building_name,location_raw,location_raw,micro_market,landmark_name,street_name,case when exists(select 1 from brokers b where b.id=src.broker_id) then src.broker_id end,broker_name,broker_phone,group_name,summary_title,normalized_message,coalesce(raw_payload,'{}'),ai_extraction,coalesce(deal_tags,'{}'),coalesce(additional_charges,'[]'),coalesce(validation_flags,'[]'),true or needs_review or asset_type is null or commercial_use_type is null,case when confidence>=.8 then 'high' when confidence>=.5 then 'medium' else 'low' end,coalesce(corrected_fields,'{}'),correction_confidence,corrected_at,created_at,now(),id,coalesce(nullif(lower(commercial_use_type),''),'mixed_use'),carpet,built,area,amount,null,price_basis,ai_extraction->'price'->>'raw_price_text',fitout_status,ceiling_height,floor_range,floor_range,car_parking_count,parking_type,oc_status,brokerage_type,developer
from src where a='commercial' and tx='sale';

with src as (select p.*,r.message source_message,public._typed_asset(p.asset_type,p.property_type,r.message) a,public._typed_tx(p.intent,p.transaction_type,r.message) tx,coalesce(p.carpet_area_sqft,public._typed_num(p.ai_extraction->>'carpet_area_sqft'),p.area_sqft) carpet,coalesce(p.built_up_area_sqft,public._typed_num(p.ai_extraction->>'built_up_area_sqft')) built,coalesce(p.monthly_rent,public._typed_money(p.price,p.price_unit)) amount,md5('parsed_output:'||p.id::text) fp from public.parsed_output p left join public.raw_messages r on r.id=p.raw_message_id where lower(coalesce(p.message_type,'')) not in ('buy','requirement') and lower(coalesce(p.intent,'')) not in ('buy','requirement','buyer'))
insert into public.commercial_rent_listings (raw_message_id,tenant_id,listing_index,source_fingerprint,building_name,locality_raw,locality_resolved,micro_market,landmark_name,street_name,broker_id,broker_name,broker_phone,group_name,summary_title,normalized_message,raw_payload,ai_extraction,deal_tags,additional_charges,validation_flags,needs_review,extraction_confidence,corrected_fields,correction_confidence,corrected_at,created_at,updated_at,legacy_source_id,commercial_use_type,carpet_area_sqft,built_up_area_sqft,area_raw_text,monthly_rent,price_basis,price_raw_text,deposit_amount,fitout_status,ceiling_height,floor_level,floor_range,car_parking_count,parking_type,oc_status,brokerage_type)
select raw_message_id,tenant_id,coalesce(listing_index,0),fp,building_name,location_raw,location_raw,micro_market,landmark_name,street_name,case when exists(select 1 from brokers b where b.id=src.broker_id) then src.broker_id end,broker_name,broker_phone,group_name,summary_title,normalized_message,coalesce(raw_payload,'{}'),ai_extraction,coalesce(deal_tags,'{}'),coalesce(additional_charges,'[]'),coalesce(validation_flags,'[]'),true or needs_review or asset_type is null or commercial_use_type is null or amount is null,case when confidence>=.8 then 'high' when confidence>=.5 then 'medium' else 'low' end,coalesce(corrected_fields,'{}'),correction_confidence,corrected_at,created_at,now(),id,coalesce(nullif(lower(commercial_use_type),''),'mixed_use'),carpet,built,area,amount,price_basis,ai_extraction->'price'->>'raw_price_text',deposit_amount,fitout_status,ceiling_height,floor_range,floor_range,car_parking_count,parking_type,oc_status,brokerage_type
from src where a='commercial' and tx='rent';

-- Requirements are copied from the already-promoted market_requirements table.
with req as (select mr.*,coalesce(nullif(lower(mr.transaction_type),''),public._typed_tx(mr.intent,'',rm.message)) tx,public._typed_asset(po.asset_type,po.property_type,rm.message) a,po.ai_extraction,po.raw_payload,po.deal_tags,po.additional_charges,po.validation_flags,po.summary_title,po.normalized_message,po.corrected_fields,po.correction_confidence,po.corrected_at,po.created_at po_created,po.message_type from public.market_requirements mr left join lateral (select p.* from public.parsed_output p where p.raw_message_id=mr.raw_message_id and lower(coalesce(p.message_type,'')) in ('buy','requirement') order by p.id desc limit 1) po on true left join public.raw_messages rm on rm.id=mr.raw_message_id)
insert into public.residential_sale_requirements (raw_message_id,tenant_id,listing_index,source_fingerprint,asset_type,transaction_type,building_name,locality_raw,locality_resolved,micro_market,landmark_name,broker_id,broker_name,broker_phone,group_name,summary_title,normalized_message,raw_payload,ai_extraction,deal_tags,additional_charges,validation_flags,needs_review,extraction_confidence,corrected_fields,correction_confidence,corrected_at,created_at,updated_at,legacy_source_id,budget_min,budget_max,budget_currency,area_min_sqft,area_max_sqft,locality_options,is_flexible,urgency,status,bhk_options,carpet_area_min_sqft,carpet_area_max_sqft,built_up_area_min_sqft,built_up_area_max_sqft)
select raw_message_id,tenant_id,0,md5('market_requirements:'||id::text),coalesce(a,'residential'),tx,building_name,location_label,location_label,micro_market,landmark_name,case when exists(select 1 from brokers b where b.id=mr.broker_id) then mr.broker_id end,broker_name,broker_phone, null,summary_title,normalized_message,coalesce(raw_payload,'{}'),ai_extraction,coalesce(deal_tags,'{}'),coalesce(additional_charges,'[]'),coalesce(validation_flags,'[]'),true,case when confidence>=.8 then 'high' when confidence>=.5 then 'medium' else 'low' end,coalesce(corrected_fields,'{}'),correction_confidence,corrected_at,coalesce(po_created,created_at),now(),id,price_min,price_max,'INR',area_sqft,area_sqft,case when location_label is null then '{}' else array[location_label] end,false,null,'active',case when bhk ~ '[0-9]' then array[public._typed_num(regexp_replace(bhk,'[^0-9.]','','g'))]::numeric[] else '{}' end,area_sqft,area_sqft,area_sqft,area_sqft
from req mr where tx='sale' and a<>'commercial';

with req as (select mr.*,coalesce(nullif(lower(mr.transaction_type),''),public._typed_tx(mr.intent,'',rm.message)) tx,public._typed_asset(po.asset_type,po.property_type,rm.message) a,po.summary_title,po.normalized_message,po.raw_payload,po.ai_extraction,po.deal_tags,po.additional_charges,po.validation_flags,po.corrected_fields,po.correction_confidence,po.corrected_at,po.created_at po_created from public.market_requirements mr left join lateral (select p.* from public.parsed_output p where p.raw_message_id=mr.raw_message_id and lower(coalesce(p.message_type,'')) in ('buy','requirement') order by p.id desc limit 1) po on true left join public.raw_messages rm on rm.id=mr.raw_message_id)
insert into public.residential_rent_requirements (raw_message_id,tenant_id,listing_index,source_fingerprint,asset_type,transaction_type,building_name,locality_raw,locality_resolved,micro_market,broker_id,broker_name,broker_phone,summary_title,normalized_message,raw_payload,ai_extraction,deal_tags,additional_charges,validation_flags,needs_review,extraction_confidence,created_at,updated_at,budget_min,budget_max,budget_currency,area_min_sqft,area_max_sqft,locality_options,status,bhk_options,carpet_area_min_sqft,carpet_area_max_sqft,deposit_budget_max)
select raw_message_id,tenant_id,0,md5('market_requirements:'||id::text),coalesce(a,'residential'),tx,building_name,location_label,location_label,micro_market,broker_id,broker_name,broker_phone,summary_title,normalized_message,coalesce(raw_payload,'{}'),ai_extraction,coalesce(deal_tags,'{}'),coalesce(additional_charges,'[]'),coalesce(validation_flags,'[]'),true,case when confidence>=.8 then 'high' when confidence>=.5 then 'medium' else 'low' end,coalesce(po_created,created_at),now(),price_min,price_max,'INR',area_sqft,area_sqft,case when location_label is null then '{}' else array[location_label] end,'active',case when bhk ~ '[0-9]' then array[public._typed_num(regexp_replace(bhk,'[^0-9.]','','g'))]::numeric[] else '{}' end,area_sqft,area_sqft,null
from req where tx='rent' and a<>'commercial';

-- Commercial requirement copies use the same provenance and shared fields; the
-- type-specific commercial fields remain null until the focused extraction bridge.
insert into public.commercial_sale_requirements (raw_message_id,tenant_id,listing_index,source_fingerprint,asset_type,transaction_type,building_name,locality_raw,locality_resolved,micro_market,broker_id,broker_name,broker_phone,raw_payload,needs_review,extraction_confidence,created_at,updated_at,budget_min,budget_max,budget_currency,area_min_sqft,area_max_sqft,status,commercial_use_type)
select mr.raw_message_id,mr.tenant_id,0,md5('market_requirements:'||mr.id::text), 'commercial','sale',mr.building_name,mr.location_label,mr.location_label,mr.micro_market,mr.broker_id,mr.broker_name,mr.broker_phone,'{}',true,'low',mr.created_at,now(),mr.price_min,mr.price_max,'INR',mr.area_sqft,mr.area_sqft,'active',array[]::text[] from public.market_requirements mr left join public.raw_messages rm on rm.id=mr.raw_message_id where coalesce(lower(nullif(mr.transaction_type,'')),public._typed_tx(mr.intent,'',rm.message))='sale' and exists(select 1 from parsed_output p where p.raw_message_id=mr.raw_message_id and public._typed_asset(p.asset_type,p.property_type,rm.message)='commercial') and not exists(select 1 from public.commercial_sale_requirements q where q.raw_message_id=mr.raw_message_id);
insert into public.commercial_rent_requirements (raw_message_id,tenant_id,listing_index,source_fingerprint,asset_type,transaction_type,building_name,locality_raw,locality_resolved,micro_market,broker_id,broker_name,broker_phone,raw_payload,needs_review,extraction_confidence,created_at,updated_at,budget_min,budget_max,budget_currency,area_min_sqft,area_max_sqft,status,commercial_use_type)
select mr.raw_message_id,mr.tenant_id,0,md5('market_requirements:'||mr.id::text), 'commercial','rent',mr.building_name,mr.location_label,mr.location_label,mr.micro_market,mr.broker_id,mr.broker_name,mr.broker_phone,'{}',true,'low',mr.created_at,now(),mr.price_min,mr.price_max,'INR',mr.area_sqft,mr.area_sqft,'active',array[]::text[] from public.market_requirements mr left join public.raw_messages rm on rm.id=mr.raw_message_id where coalesce(lower(nullif(mr.transaction_type,'')),public._typed_tx(mr.intent,'',rm.message))='rent' and exists(select 1 from parsed_output p where p.raw_message_id=mr.raw_message_id and public._typed_asset(p.asset_type,p.property_type,rm.message)='commercial') and not exists(select 1 from public.commercial_rent_requirements q where q.raw_message_id=mr.raw_message_id);

-- Backfill review flags for missing critical fields and suspicious price-period mixes.
update public.residential_sale_listings set needs_review=true where total_asking_price is null and price_per_sqft is null;
update public.residential_rent_listings set needs_review=true where monthly_rent is null and rent_per_sqft is null;
update public.commercial_sale_listings set needs_review=true where total_asking_price is null and price_per_sqft is null;
update public.commercial_rent_listings set needs_review=true where monthly_rent is null and rent_per_sqft is null;

do $$ declare t text; begin foreach t in array array['residential_sale_listings','residential_rent_listings','commercial_sale_listings','commercial_rent_listings','residential_sale_requirements','residential_rent_requirements','commercial_sale_requirements','commercial_rent_requirements'] loop
  execute format('alter table public.%I enable row level security',t);
  execute format('drop policy if exists service_role_all_%I on public.%I',t,t);
  execute format('create policy service_role_all_%I on public.%I for all to service_role using (true) with check (true)',t,t);
  execute format('create index if not exists idx_%I_tenant on public.%I(tenant_id)',t,t);
  execute format('create index if not exists idx_%I_raw on public.%I(raw_message_id)',t,t);
  execute format('create index if not exists idx_%I_created on public.%I(created_at desc)',t,t);
  execute format('create index if not exists idx_%I_review on public.%I(needs_review) where needs_review=true',t,t);
  execute format('create index if not exists idx_%I_locality on public.%I(micro_market)',t,t);
end loop; end $$;
create index if not exists idx_res_sale_price_typed on public.residential_sale_listings(total_asking_price);
create index if not exists idx_res_rent_price_typed on public.residential_rent_listings(monthly_rent);
create index if not exists idx_comm_sale_price_typed on public.commercial_sale_listings(total_asking_price);
create index if not exists idx_comm_rent_price_typed on public.commercial_rent_listings(monthly_rent);
create index if not exists idx_res_sale_req_bhk on public.residential_sale_requirements using gin(bhk_options);
create index if not exists idx_res_rent_req_bhk on public.residential_rent_requirements using gin(bhk_options);
create unique index if not exists uq_res_sale_source on public.residential_sale_listings(source_fingerprint);
create unique index if not exists uq_res_rent_source on public.residential_rent_listings(source_fingerprint);
create unique index if not exists uq_comm_sale_source on public.commercial_sale_listings(source_fingerprint);
create unique index if not exists uq_comm_rent_source on public.commercial_rent_listings(source_fingerprint);
create unique index if not exists uq_res_sale_req_source on public.residential_sale_requirements(source_fingerprint);
create unique index if not exists uq_res_rent_req_source on public.residential_rent_requirements(source_fingerprint);
create unique index if not exists uq_comm_sale_req_source on public.commercial_sale_requirements(source_fingerprint);
create unique index if not exists uq_comm_rent_req_source on public.commercial_rent_requirements(source_fingerprint);

drop view if exists public.parsed_output_unified;
create view public.parsed_output_unified as
select 'residential_sale' card_type,id,raw_message_id,tenant_id,building_name,micro_market,broker_name,broker_phone,bhk::text bhk,carpet_area_sqft area_sqft,total_asking_price price,'sale' transaction_type,needs_review,created_at from public.residential_sale_listings
union all select 'residential_rent',id,raw_message_id,tenant_id,building_name,micro_market,broker_name,broker_phone,bhk::text,carpet_area_sqft,monthly_rent,'rent',needs_review,created_at from public.residential_rent_listings
union all select 'commercial_sale',id,raw_message_id,tenant_id,building_name,micro_market,broker_name,broker_phone,null,carpet_area_sqft,total_asking_price,'sale',needs_review,created_at from public.commercial_sale_listings
union all select 'commercial_rent',id,raw_message_id,tenant_id,building_name,micro_market,broker_name,broker_phone,null,carpet_area_sqft,monthly_rent,'rent',needs_review,created_at from public.commercial_rent_listings;

drop view if exists public.requirements_unified;
create view public.requirements_unified as
select 'residential_sale' req_type,id,raw_message_id,tenant_id,building_name,micro_market,broker_name,broker_phone,bhk_options,budget_min,budget_max,carpet_area_min_sqft,carpet_area_max_sqft,status,created_at from public.residential_sale_requirements
union all select 'residential_rent',id,raw_message_id,tenant_id,building_name,micro_market,broker_name,broker_phone,bhk_options,budget_min,budget_max,carpet_area_min_sqft,carpet_area_max_sqft,status,created_at from public.residential_rent_requirements
union all select 'commercial_sale',id,raw_message_id,tenant_id,building_name,micro_market,broker_name,broker_phone,'{}',budget_min,budget_max,carpet_area_min_sqft,carpet_area_max_sqft,status,created_at from public.commercial_sale_requirements
union all select 'commercial_rent',id,raw_message_id,tenant_id,building_name,micro_market,broker_name,broker_phone,'{}',budget_min,budget_max,carpet_area_min_sqft,carpet_area_max_sqft,status,created_at from public.commercial_rent_requirements;

-- Preserve the old data exactly, but make the old names unavailable so accidental
-- writes cannot silently populate the deprecated schema after this cutover.
alter table public.parsed_output rename to parsed_output_legacy;
alter table public.listings rename to listings_legacy;
alter table public.market_requirements rename to market_requirements_legacy;

insert into supabase_migrations.schema_migrations(version,name) values ('20260803020000','typed_extraction_schemas') on conflict (version) do nothing;
commit;
